<?php
/** Native pricing contract, content safety and feature-capacity boundaries. */
if ( ! defined( 'WP_CLI' ) || ! WP_CLI || home_url() !== getenv( 'MRN_STACK_TEST_HOME' ) || ! str_ends_with( (string) wp_parse_url( home_url(), PHP_URL_HOST ), '.localhost' ) || ! current_user_can( 'manage_options' ) ) { throw new RuntimeException( 'An explicitly selected local administrator runtime is required.' ); }
$checks = array(); $expect = static function ( $ok, $label ) use ( &$checks ) { if ( ! $ok ) { throw new RuntimeException( esc_html( $label ) ); } $checks[] = $label; };
$layouts = array_column( acf_get_field( 'field_mrn_page_content_rows' )['layouts'], null, 'name' ); $fields = array_column( $layouts['card']['sub_fields'], null, 'name' ); $items = array_column( $fields['card_items']['sub_fields'], null, 'name' );
$expect( isset( $fields['card_presentation']['choices']['pricing'] ) && 'standard' === $fields['card_presentation']['default_value'], 'Pricing is optional; the existing default remains Standard' );
$expect( 1 === $items['card_rows']['max'] && 1 === $items['card_rows']['min'], 'Existing single Card Row contract is retained' );
