foreach ( array( 'pricing_badge', 'pricing_highlight', 'pricing_description', 'pricing_action', 'pricing_features' ) as $name ) { $expect( isset( $items[ $name ], $alternate[ $name ] ) && $items[ $name ]['key'] !== $alternate[ $name ]['key'], 'Pricing factory keys are isolated: ' . $name ); }
$row = array( 'acf_fc_layout' => 'card', 'card_presentation' => 'pricing', 'card_frame' => 'contained', 'heading' => 'Plans <script>alert(1)</script>', 'subheading' => 'Exact & plain text', 'pricing_name_size' => 'var(--site-text-h4-size)', 'pricing_description_line_height' => '1', 'pricing_text_color' => 'charcoal', 'pricing_padding_block' => '32px', 'card_items' => array( array( 'card_label' => 'Plan <em>name</em>', 'pricing_badge' => '$42 / month', 'pricing_description' => 'Exact plain <strong>description</strong>', 'pricing_highlight' => 1, 'pricing_features' => array( array( 'text' => 'A & B <script>alert(2)</script>' ) ), 'pricing_action' => array( 'title' => 'Review & choose', 'url' => home_url( '/keep/?a=1&b=2' ), 'target' => '_blank' ) ) ) );
