foreach ( array( '--mrn-pricing-name-size:var(--site-text-h4-size)', '--mrn-pricing-description-line-height:1', '--mrn-pricing-text-color:var(--site-color-charcoal)', '--mrn-pricing-padding-block:32px' ) as $part ) { $expect( str_contains( $style, $part ), 'Validated native style: ' . $part ); }
foreach ( array( '-1px', '1px;color:red', 'var(--unknown)', array( '12px' ) ) as $bad ) { $expect( ! mrn_base_stack_get_pricing_styles( array( 'card_presentation' => 'pricing', 'pricing_name_size' => $bad, 'pricing_text_color' => $bad, 'pricing_padding_block' => $bad ) ), 'Invalid values cannot emit arbitrary CSS' ); }
$expect( ! mrn_base_stack_get_pricing_styles( array_replace( $row, array( 'card_presentation' => 'standard' ) ) ), 'Unselected pricing ignores dormant styles' );
ob_start(); mrn_base_stack_render_builder_rows( array( $row ), get_the_ID(), 'page_content_rows' ); $html = ob_get_clean();
$expect( str_contains( $html, '&lt;script&gt;' ) && ! str_contains( $html, '<script' ) && str_contains( $html, 'Plan &lt;em&gt;name&lt;/em&gt;' ), 'Every plain copy field escapes markup' );
$expect( str_contains( $html, 'href="' . esc_url( home_url( '/keep/?a=1&b=2' ) ) . '"' ) && str_contains( $html, 'target="_blank" rel="noopener noreferrer"' ), 'Independent action preserves complete URL and secures new tabs' );
$expect( str_contains( $html, '<ul class="mrn-pricing-cards__features">' ) && str_contains( $html, 'aria-hidden="true" focusable="false"' ) && ! str_contains( $html, 'tabindex="0"' ), 'Semantic feature list, decorative icons and no extra keyboard stops' );
$row['card_items'][0]['pricing_action']['url'] = 'javascript:alert(1)'; ob_start(); mrn_base_stack_render_builder_rows( array( $row ), get_the_ID(), 'page_content_rows' ); $unsafe = ob_get_clean(); $expect( ! str_contains( $unsafe, 'href="javascript:' ), 'Unsafe protocols cannot render executable actions' );
$standard = array( 'acf_fc_layout' => 'card', 'card_items' => array( array( 'card_label' => 'Existing standard card', 'pricing_badge' => 'Dormant pricing data', 'pricing_features' => array( array( 'text' => 'Dormant feature' ) ) ) ) ); ob_start(); mrn_base_stack_render_builder_rows( array( $standard ), get_the_ID(), 'page_content_rows' ); $legacy = ob_get_clean(); $expect( str_contains( $legacy, 'Existing standard card' ) && ! str_contains( $legacy, 'Dormant' ) && ! str_contains( $legacy, 'has-pricing-cards' ), 'Existing Standard output ignores dormant pricing content' );
WP_CLI::line( wp_json_encode( array( 'result' => 'passed', 'count' => count( $checks ), 'checks' => $checks, 'candidate_only' => true ), JSON_PRETTY_PRINT ) );
